import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;

public class BellGameTests {
    private static final BlockPos P=new BlockPos(4,5,4);
    private static BlockState bell(AbstractBellBlock block,BellAttachType attachment,Direction facing) { return block.defaultBlockState().setValue(BellBlock.ATTACHMENT,attachment).setValue(BellBlock.FACING,facing); }
    private static PeculiarBellBlockEntity peculiar(GameTestHelper h) { h.setBlock(P.below(),Blocks.STONE);h.setBlock(P,bell(AllBlocks.PECULIAR_BELL,BellAttachType.FLOOR,Direction.NORTH));return h.getBlockEntity(P,PeculiarBellBlockEntity.class); }
    private static HauntedBellBlockEntity haunted(GameTestHelper h) { h.setBlock(P.below(),Blocks.STONE);h.setBlock(P,bell(AllBlocks.HAUNTED_BELL,BellAttachType.FLOOR,Direction.NORTH));return h.getBlockEntity(P,HauntedBellBlockEntity.class); }
    private static DeskBellBlockEntity desk(GameTestHelper h) { h.setBlock(P.below(),Blocks.STONE);h.setBlock(P,AllBlocks.DESK_BELL);return h.getBlockEntity(P,DeskBellBlockEntity.class); }
    private static void ding(GameTestHelper h) { var pos=h.absolutePos(P);h.getBlockState(P).useWithoutItem(h.getLevel(),h.makeMockPlayer(GameType.SURVIVAL),new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false)); }
    private static boolean pressed(GameTestHelper h) { return h.getBlockState(P).getValue(DeskBellBlock.POWERED); }
    private static ControlledContraptionEntity moving(GameTestHelper h,BlockState state,Consumer<BlockEntity> prepare)throws Exception {
        h.setBlock(P.below(),Blocks.STONE);h.setBlock(P,state);h.setBlock(P.east(),Blocks.BARREL);prepare.accept(h.getLevel().getBlockEntity(h.absolutePos(P)));
        h.getLevel().addFreshEntity(new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(P),h.absolutePos(P.east()))));var structure=new BearingContraption(false,Direction.UP);h.assertTrue(structure.assemble(h.getLevel(),h.absolutePos(P.east().below())),"Assemble bell/campfire");h.assertTrue(structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO),"Take ownership");var owner=new ControlledContraptionEntity(AllEntityTypes.CONTROLLED_CONTRAPTION,h.getLevel());owner.setContraption(structure);owner.setPos(Vec3.atLowerCornerOf(h.absolutePos(P.east())));owner.tickActors();return owner;
    }
    private static MovementContext ctx(ControlledContraptionEntity owner) { return owner.getContraption().getActors().getFirst().right; }
    private static void campfireContents(GameTestHelper h,BlockEntity entity) { var fire=(CampfireBlockEntity)entity;var food=new ItemStack(Items.BEEF);food.set(DataComponents.CUSTOM_NAME,Component.literal("Moving meal"));fire.getItems().set(0,food);var tag=fire.saveWithFullMetadata(h.getLevel().registryAccess());tag.putIntArray("CookingTimes",new int[]{17,0,0,0});tag.putIntArray("CookingTotalTimes",new int[]{600,0,0,0});fire.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,h.getLevel().registryAccess(),tag)); }
    @GameTest public void allSourceBellAndCampfireActorsAreRegistered(GameTestHelper h) {
        for(var block:List.of(Blocks.BELL,AllBlocks.PECULIAR_BELL,AllBlocks.DESK_BELL))h.assertTrue(MovementBehaviour.REGISTRY.get(block) instanceof BellMovementBehaviour,"Normal bell actor");h.assertTrue(MovementBehaviour.REGISTRY.get(AllBlocks.HAUNTED_BELL) instanceof HauntedBellMovementBehaviour,"Haunted actor");for(var block:List.of(Blocks.CAMPFIRE,Blocks.SOUL_CAMPFIRE))h.assertTrue(MovementBehaviour.REGISTRY.get(block) instanceof CampfireMovementBehaviour,"Campfire actor");h.succeed();
    }
    @GameTest public void customBellSelectionShapesPreserveSourceAttachments(GameTestHelper h) {
        for(var facing:Direction.Plane.HORIZONTAL){var shape=BellShapes.bell(BellAttachType.FLOOR,facing);h.assertValueEqual(shape.max(Direction.Axis.Y),13/16d,"Source bell body height");h.assertValueEqual(shape.max(facing.getAxis()==Direction.Axis.X?Direction.Axis.Z:Direction.Axis.X),1d,"Floor frame width");h.assertValueEqual(BellShapes.bell(BellAttachType.CEILING,facing).max(Direction.Axis.Y),1d,"Ceiling attachment");}
        h.assertValueEqual(BellShapes.bell(BellAttachType.SINGLE_WALL,Direction.SOUTH).max(Direction.Axis.Z),1d,"Source south wall");h.assertValueEqual(BellShapes.bell(BellAttachType.SINGLE_WALL,Direction.NORTH).min(Direction.Axis.Z),0d,"Source north wall");h.succeed();
    }
    @GameTest public void sourceRingFaceAndHeightRulesCoverAllAttachments(GameTestHelper h) {
        for(var attachment:BellAttachType.values())for(var facing:Direction.Plane.HORIZONTAL){var state=bell(AllBlocks.PECULIAR_BELL,attachment,facing);for(var hit:Direction.values()){boolean wall=attachment==BellAttachType.SINGLE_WALL||attachment==BellAttachType.DOUBLE_WALL;boolean expected=!hit.getAxis().isVertical()&&(wall?hit.getAxis()!=facing.getAxis():hit.getAxis()==facing.getAxis());h.assertTrue(AllBlocks.PECULIAR_BELL.canRingFrom(state,hit,.5)==expected,"Attachment/face rule");h.assertFalse(AllBlocks.PECULIAR_BELL.canRingFrom(state,hit,.9),"Upper frame is not bell head");}}h.succeed();
    }
    @GameTest public void directUseStartsTheCustomBellAndInvalidSideDoesNot(GameTestHelper h) {
        var be=peculiar(h);var pos=h.absolutePos(P);var player=h.makeMockPlayer(GameType.SURVIVAL);h.assertFalse(AllBlocks.PECULIAR_BELL.onHit(h.getLevel(),h.getBlockState(P),new BlockHitResult(Vec3.atCenterOf(pos),Direction.EAST,pos,false),player,true),"Floor bell side axis");h.assertFalse(be.isRinging,"Invalid hit leaves state");h.assertTrue(AllBlocks.PECULIAR_BELL.onHit(h.getLevel(),h.getBlockState(P),new BlockHitResult(Vec3.atCenterOf(pos),Direction.SOUTH,pos,false),player,true)&&be.isRinging&&be.ringDirection==Direction.SOUTH,"Custom BE rings through native onHit");h.succeed();
    }
    @GameTest public void ringAnimationStopsAfterSeventyFourTicks(GameTestHelper h) {
        var be=peculiar(h);be.ring(h.getLevel(),h.absolutePos(P),Direction.NORTH);for(int i=0;i<73;i++)AbstractBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);h.assertTrue(be.isRinging&&be.ringingTicks==73,"Source duration before final tick");AbstractBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);h.assertTrue(!be.isRinging&&be.ringingTicks==0,"Source duration complete");h.succeed();
    }
    @GameTest public void renderSnapshotContainsProgressButPrivateSaveDoesNotRestartRinging(GameTestHelper h) {
        var be=peculiar(h);be.ring(h.getLevel(),h.absolutePos(P),Direction.WEST);for(int i=0;i<9;i++)AbstractBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);
        var update=be.getUpdateTag(h.getLevel().registryAccess());var saved=be.saveWithFullMetadata(h.getLevel().registryAccess());h.assertTrue(update.getBooleanOr("Ringing",false)&&update.getIntOr("RingingTicks",0)==9&&!saved.contains("Ringing"),"Detached progress versus transient source ring");var restored=(PeculiarBellBlockEntity)BlockEntity.loadStatic(h.absolutePos(P),h.getBlockState(P),saved,h.getLevel().registryAccess());h.assertFalse(restored.isRinging,"Ordinary server load does not replay transient ring");h.succeed();
    }
    @GameTest(maxTicks=50) public void redstoneRisingEdgeRingsOnceAndFallingEdgeDoesNot(GameTestHelper h) {
        var be=peculiar(h);h.setBlock(P.east(),Blocks.REDSTONE_BLOCK);h.runAfterDelay(4,()->{long sequence=be.getUpdateTag(h.getLevel().registryAccess()).getLongOr("RingSequence",0);h.assertValueEqual(sequence,1L,"Single rising edge");h.setBlock(P.west(),Blocks.STONE);h.runAfterDelay(4,()->{h.assertValueEqual(be.getUpdateTag(h.getLevel().registryAccess()).getLongOr("RingSequence",0),sequence,"Sustained power/other neighbor does not retrigger");h.setBlock(P.east(),Blocks.AIR);h.runAfterDelay(4,()->{h.assertValueEqual(be.getUpdateTag(h.getLevel().registryAccess()).getLongOr("RingSequence",0),sequence,"Falling edge silent");h.setBlock(P.east(),Blocks.REDSTONE_BLOCK);h.runAfterDelay(3,()->{h.assertValueEqual(be.getUpdateTag(h.getLevel().registryAccess()).getLongOr("RingSequence",0),sequence+1,"Second rising edge");h.succeed();});});});});
    }
    @GameTest(maxTicks=50) public void realArrowCanRingACustomBell(GameTestHelper h) { var be=peculiar(h);var arrow=h.spawn(EntityTypes.ARROW,P.south(3));arrow.setNoGravity(true);arrow.shoot(0,0,-1,1.5f,0);h.succeedWhen(()->h.assertTrue(be.isRinging,"Native projectile reaches custom onHit")); }
    @GameTest public void hauntedBellRejectsEarlyRingAndAcceptsAtSixtyFive(GameTestHelper h) {
        var be=haunted(h);h.assertTrue(be.ring(h.getLevel(),h.absolutePos(P),Direction.NORTH),"First ring");for(int i=0;i<64;i++)AbstractBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);h.assertFalse(be.ring(h.getLevel(),h.absolutePos(P),Direction.SOUTH),"Cooldown before65");AbstractBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);h.assertTrue(be.ring(h.getLevel(),h.absolutePos(P),Direction.SOUTH)&&be.effectTicks==20&&be.ringingTicks==0,"Ready at65");h.succeed();
    }
    @GameTest public void hauntedPlacementAndEffectCountdownPersistSeparately(GameTestHelper h) {
        var be=haunted(h);h.assertValueEqual(be.effectTicks,20,"Awakens on placement");for(int i=0;i<8;i++)AbstractBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);var restored=(HauntedBellBlockEntity)BlockEntity.loadStatic(h.absolutePos(P),h.getBlockState(P),be.saveWithFullMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(restored.effectTicks==12&&!restored.isRinging,"EffectTicks is persistent, ring is transient");h.succeed();
    }
    @GameTest public void soulFireConvertsSupportedPeculiarBell(GameTestHelper h) { h.setBlock(P.below(2),Blocks.SOUL_SAND);h.setBlock(P.above(),Blocks.STONE);h.setBlock(P,bell(AllBlocks.PECULIAR_BELL,BellAttachType.CEILING,Direction.EAST));h.setBlock(P.below(),Blocks.SOUL_FIRE);h.assertTrue(h.getBlockState(P).is(AllBlocks.HAUNTED_BELL),"Actual neighbor conversion");h.assertTrue(h.getBlockState(P).getValue(BellBlock.ATTACHMENT)==BellAttachType.CEILING&&h.getBlockState(P).getValue(BellBlock.FACING)==Direction.EAST,"Attachment/facing preserved");h.succeed(); }
    @GameTest public void unlitSoulCampfireStillConvertsAsInSource(GameTestHelper h) { h.setBlock(P.above(),Blocks.STONE);h.setBlock(P,bell(AllBlocks.PECULIAR_BELL,BellAttachType.CEILING,Direction.WEST));h.setBlock(P.below(),Blocks.SOUL_CAMPFIRE.defaultBlockState().setValue(CampfireBlock.LIT,false));h.assertTrue(h.getBlockState(P).is(AllBlocks.HAUNTED_BELL),"Source conversion does not require LIT");h.succeed(); }
    @GameTest public void conversionShapeResultPreservesAllThreeProperties(GameTestHelper h) { h.setBlock(P.above(),Blocks.STONE);var input=bell(AllBlocks.PECULIAR_BELL,BellAttachType.CEILING,Direction.SOUTH).setValue(BellBlock.POWERED,true);var result=input.updateShape(h.getLevel(),h.getLevel(),h.absolutePos(P),Direction.DOWN,h.absolutePos(P.below()),Blocks.SOUL_CAMPFIRE.defaultBlockState(),h.getLevel().getRandom());h.assertTrue(result.is(AllBlocks.HAUNTED_BELL)&&result.getValue(BellBlock.POWERED)&&result.getValue(BellBlock.FACING)==Direction.SOUTH&&result.getValue(BellBlock.ATTACHMENT)==BellAttachType.CEILING,"Conversion retains source state");h.succeed(); }
    @GameTest public void ordinaryFireDoesNotConvertPeculiarBell(GameTestHelper h) { peculiar(h);h.setBlock(P.south(),Blocks.FIRE);h.assertTrue(h.getBlockState(P).is(AllBlocks.PECULIAR_BELL),"Only specified soul blocks convert");h.succeed(); }
    @GameTest public void onlyDeskBellUsesSourceWrenchInterface(GameTestHelper h) { peculiar(h);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));var pos=h.absolutePos(P);var hit=new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false);h.assertTrue(AllItems.WRENCH.useOn(new net.minecraft.world.item.context.UseOnContext(player,InteractionHand.MAIN_HAND,hit))==InteractionResult.PASS,"Source peculiar/haunted bells are not IWrenchable");h.succeed(); }
    @GameTest public void deskSelectionGeometryCoversSixOrientations(GameTestHelper h) { for(var facing:Direction.values()){var bounds=BellShapes.desk(facing).bounds();double reach=facing.getAxisDirection()==Direction.AxisDirection.POSITIVE?bounds.max(facing.getAxis()):1-bounds.min(facing.getAxis());h.assertValueEqual(reach,9/16d,"Source desk bell height along facing");}h.succeed(); }
    @GameTest public void deskClickSetsTwentyTickPulse(GameTestHelper h) { var be=desk(h);ding(h);h.assertTrue(pressed(h)&&be.getPressTimer()==20,"Source click starts20");for(int i=0;i<19;i++)DeskBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);h.assertTrue(pressed(h)&&be.getPressTimer()==1,"Pulse lasts full duration");DeskBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);h.assertFalse(pressed(h),"Pulse releases at20");h.succeed(); }
    @GameTest public void repeatedDeskClickExtendsPulse(GameTestHelper h) { var be=desk(h);ding(h);for(int i=0;i<12;i++)DeskBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);ding(h);h.assertValueEqual(be.getPressTimer(),20,"Second click resets timer");h.succeed(); }
    @GameTest public void deskStrongPowerOnlyPointsAlongFacing(GameTestHelper h) { for(var facing:Direction.values()){var state=AllBlocks.DESK_BELL.defaultBlockState().setValue(DeskBellBlock.FACING,facing).setValue(DeskBellBlock.POWERED,true);for(var side:Direction.values()){h.assertValueEqual(state.getSignal(h.getLevel(),h.absolutePos(P),side),15,"Weak power all sides");h.assertValueEqual(state.getDirectSignal(h.getLevel(),h.absolutePos(P),side),side==facing?15:0,"Strong power source direction");}}h.succeed(); }
    @GameTest(maxTicks=60) public void deskPulseDrivesActualWireAndReleasesIt(GameTestHelper h) { desk(h);h.setBlock(P.east().below(),Blocks.STONE);h.setBlock(P.east(),Blocks.REDSTONE_WIRE);ding(h);h.runAfterDelay(3,()->{h.assertValueEqual(h.getBlockState(P.east()).getValue(RedstoneWireBlock.POWER),15,"Real wire powered");h.runAfterDelay(23,()->{h.assertFalse(pressed(h),"Real ticker release");h.assertValueEqual(h.getBlockState(P.east()).getValue(RedstoneWireBlock.POWER),0,"Real wire released");h.succeed();});}); }
    @GameTest public void deskSnapshotsDoNotConsumePendingDing(GameTestHelper h) { var be=desk(h);ding(h);var first=be.getUpdateTag(h.getLevel().registryAccess());be.saveWithFullMetadata(h.getLevel().registryAccess());var second=be.getUpdateTag(h.getLevel().registryAccess());h.assertTrue(first.getLongOr("DingSequence",0)==1&&second.getLongOr("DingSequence",0)==1&&second.getIntOr("PressTimer",0)==20,"Saving cannot swallow a client ding marker");h.succeed(); }
    @GameTest public void deskRemainingPulseSurvivesNativeSaveAndRestore(GameTestHelper h) { var be=desk(h);ding(h);for(int i=0;i<12;i++)DeskBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);var loaded=(DeskBellBlockEntity)BlockEntity.loadStatic(h.absolutePos(P),h.getBlockState(P),be.saveWithFullMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());loaded.setLevel(h.getLevel());h.getLevel().setBlockEntity(loaded);h.assertValueEqual(loaded.getPressTimer(),8,"Actual remaining timer restored");for(int i=0;i<8;i++)DeskBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),loaded);h.assertFalse(pressed(h),"Restored timer cannot strand power");h.succeed(); }
    @GameTest public void legacyPressedDeskWithoutTimerRecovers(GameTestHelper h) { var be=desk(h);ding(h);var tag=be.saveWithFullMetadata(h.getLevel().registryAccess());tag.remove("PressTimer");be.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,h.getLevel().registryAccess(),tag));DeskBellBlockEntity.tick(h.getLevel(),h.absolutePos(P),h.getBlockState(P),be);h.assertFalse(pressed(h),"Legacy source timer omission is recoverable");h.succeed(); }
    @GameTest public void deskWaterloggingAndWrenchRetainState(GameTestHelper h) { desk(h);var state=h.getBlockState(P).setValue(DeskBellBlock.WATERLOGGED,true);h.setBlock(P,state);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));var pos=h.absolutePos(P);var hit=new BlockHitResult(Vec3.atCenterOf(pos),Direction.NORTH,pos,false);AllItems.WRENCH.useOn(new net.minecraft.world.item.context.UseOnContext(player,InteractionHand.MAIN_HAND,hit));h.assertTrue(h.getBlockState(P).getValue(DeskBellBlock.WATERLOGGED)&&h.getBlockState(P).getValue(DeskBellBlock.FACING)!=Direction.UP&&h.getBlockState(P).getFluidState().is(net.minecraft.world.level.material.Fluids.WATER),"Source rotation preserves waterlogged shape");h.succeed(); }
    @GameTest public void hauntedActorCooldownAndFirstSaveUseLatestExtraData(GameTestHelper h)throws Exception { var owner=moving(h,bell(AllBlocks.HAUNTED_BELL,BellAttachType.FLOOR,Direction.NORTH),be->{});var actor=(HauntedBellMovementBehaviour)MovementBehaviour.REGISTRY.get(AllBlocks.HAUNTED_BELL);actor.visitNewPosition(ctx(owner),h.absolutePos(P));h.assertValueEqual(actor.getRecharge(ctx(owner)),65,"Moving pulse recharge");for(int i=0;i<18;i++)actor.tick(ctx(owner));var saved=owner.getContraption().writeNBT(h.getLevel().registryAccess(),false);var loaded=Contraption.fromNBT(h.getLevel(),saved,false).getActors().getFirst().right;h.assertValueEqual(actor.getRecharge(loaded),47,"First save captures writeExtraData before copying BE NBT");h.succeed(); }
    @GameTest public void disabledHauntedActorRetainsCooldownAndControlState(GameTestHelper h)throws Exception { var owner=moving(h,bell(AllBlocks.HAUNTED_BELL,BellAttachType.FLOOR,Direction.NORTH),be->{});var actor=(HauntedBellMovementBehaviour)MovementBehaviour.REGISTRY.get(AllBlocks.HAUNTED_BELL);actor.visitNewPosition(ctx(owner),h.absolutePos(P));owner.getContraption().setActorsActive(new ItemStack(AllBlocks.HAUNTED_BELL),false);for(int i=0;i<12;i++)owner.tickActors();h.assertTrue(ctx(owner).disabled&&actor.getRecharge(ctx(owner))==65,"Disabled actor stops recharge clock");h.succeed(); }
    @GameTest public void movingDeskTimerIsFrozenAndRestoredWithoutWorldTick(GameTestHelper h)throws Exception { var owner=moving(h,AllBlocks.DESK_BELL.defaultBlockState().setValue(DeskBellBlock.POWERED,true),be->((DeskBellBlockEntity)be).ding());for(int i=0;i<60;i++)owner.tickActors();h.assertValueEqual(ctx(owner).blockEntityData.getIntOr("PressTimer",0),20,"Actor never runs server BE ticker");h.assertTrue(owner.disassemble(),"Restore");h.assertValueEqual(h.getBlockEntity(P,DeskBellBlockEntity.class).getPressTimer(),20,"Frozen source timer restored");h.succeed(); }
    @GameTest public void campfireCaptureDoesNotDropOrMountDuplicateFood(GameTestHelper h)throws Exception { var owner=moving(h,Blocks.CAMPFIRE.defaultBlockState(),be->campfireContents(h,be));h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(h.absolutePos(P)).inflate(3)).isEmpty(),"Removal suppresses campfire food drop");h.assertFalse(owner.getContraption().getStorage().getAllItemStorages().containsKey(new BlockPos(-1,0,0)),"No second food inventory");h.succeed(); }
    @GameTest public void movingCampfireDoesNotCookAndRestoresExactFoodComponents(GameTestHelper h)throws Exception { var owner=moving(h,Blocks.CAMPFIRE.defaultBlockState().setValue(CampfireBlock.SIGNAL_FIRE,true),be->campfireContents(h,be));var payload=ctx(owner).blockEntityData.copy();for(int i=0;i<120;i++)owner.tickActors();h.assertTrue(payload.equals(ctx(owner).blockEntityData),"No server food cooking in actor");h.assertTrue(owner.disassemble(),"Restore fire");var be=h.getBlockEntity(P,CampfireBlockEntity.class);h.assertTrue(be.getItems().getFirst().is(Items.BEEF)&&be.getItems().getFirst().has(DataComponents.CUSTOM_NAME)&&be.getItems().getFirst().getCount()==1,"Original component-bearing raw meal restored");var saved=be.saveWithFullMetadata(h.getLevel().registryAccess());h.assertTrue(saved.get("CookingTimes").equals(payload.get("CookingTimes"))&&saved.get("CookingTotalTimes").equals(payload.get("CookingTotalTimes")),"Native cooking progress preserved");h.succeed(); }
}
